 /** Own-history removal is idempotent. The row lock serializes removal with final replies and confirmed domain actions. */
 async remove(u:AuthUser,digest:string,id:string):Promise<AskThreadRemoval>{
  return this.db.transaction(async c=>{
   const actor=await staffOrganizationAccess(c,this.config,u,digest,{permission:'properties.read'}),ready=(await c.query("SELECT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='ask_threads' AND column_name='deleted_at') AS ready")).rows[0]?.ready;
   if(!ready)throw new ApiError(503,'ASK_HISTORY_MIGRATION_REQUIRED','Apply the pending application update before removing conversations.');
   const thread=(await c.query('SELECT id,deleted_at FROM ask_threads WHERE organization_id=$1 AND actor_user_id=$2 AND actor_membership_id=$3 AND id=$4 FOR UPDATE',[actor.organization.id,actor.id,actor.membershipId,id])).rows[0];
   if(!thread)throw new ApiError(404,'ASK_THREAD_NOT_FOUND','This thread is unavailable in your current user and organization.');
   if(thread.deleted_at)return{removed:true};
   await this.row(c,actor,digest,id);
   await c.query('UPDATE ask_threads SET deleted_at=clock_timestamp() WHERE id=$1 AND organization_id=$2',[id,actor.organization.id]);
   await c.query("INSERT INTO audit_events(organization_id,actor_user_id,action,metadata) VALUES($1,$2,'ask.thread_removed',$3)",[actor.organization.id,actor.id,JSON.stringify({threadId:id})]);
   return{removed:true};
  });
 }
